def experiment(inputs):
    import random
    granularity_levels = inputs.get('granularity_levels', [0.1, 0.5, 1.0])
    seeds = inputs.get('seeds', [12345])
    variances = []
    for seed in seeds:
        random.seed(seed)
        for g in granularity_levels:
            # simulate variance inversely related to granularity with bounded noise
            var = 0.05 + (0.02 * random.random() / g)
            variances.append(var)
    mean_var = sum(variances) / len(variances)
    return {'measurements': {'prediction_error_variance': [mean_var]}}

def experiment(inputs):
    import random
    random.seed(inputs.get('seed', 42))
    trials = inputs.get('trials', 20)
    scores = [0.85 if random.random() > 0.2 else 0.75 for _ in range(trials)]
    return {'measurements': {'identity_consistency': scores}}

def experiment(inputs):
    import random
    trials = inputs.get('trials', 10)
    scores = []
    for t in range(trials):
        scores.append(random.random() * 0.5 + 0.5)
    return {'measurements': {'preference_stability': scores}}

def experiment(inputs):
    import random
    random.seed(inputs.get('seed', 42))
    trials = inputs.get('trials', 20)
    scores = []
    for t in range(trials):
        base = 0.6 + (random.random() * 0.3)
        scores.append(base)
    return {'measurements': {'preference_stability': scores}}

def experiment(inputs):
    import random
    adaptations = 0
    for trial in inputs['trials']:
        if trial['error_detected'] and trial['causal_model_updated']:
            if trial['behavior_adapted']:
                adaptations += 1
    return {'adaptation_rate': adaptations / len(inputs['trials'])}

def experiment(inputs):
    import random
    agents = inputs.get('agents', ['causal', 'non-causal'])
    trials = inputs.get('trials', 10)
    results = {}
    for agent in agents:
        score = 0
        for t in range(trials):
            error = random.random()
            if agent == 'causal' and error < 0.5:
                score += 1
            elif agent == 'non-causal':
                score += 0.2
        results[agent] = score
    return results

